7. /// <summary>
8. /// In-memory manual override store keyed by business date and break key. Adding the same
9. /// override twice is a no-op, keeping override application deterministic across reruns.
10. /// This store deliberately implements no approval workflow or history.
11. /// </summary>
12. public sealed class InMemoryManualOverrideStore : IManualOverrideStore
13. {
14.     private readonly ConcurrentDictionary<DateOnly, ConcurrentDictionary<string, ManualOverride>> _byDate = new();
15. 
16.     public Task<IReadOnlySet<string>> GetOverriddenBreakKeysAsync(
17.         DateOnly businessDate,
18.         CancellationToken cancellationToken = default)
19.     {
20.         IReadOnlySet<string> keys = _byDate.TryGetValue(businessDate, out var map)
21.             ? map.Keys.ToHashSet(StringComparer.Ordinal)
22.             : new HashSet<string>(StringComparer.Ordinal);
23.         return Task.FromResult(keys);
24.     }
25. 
26.     public Task AddAsync(ManualOverride manualOverride, CancellationToken cancellationToken = default)
27.     {
28.         ArgumentNullException.ThrowIfNull(manualOverride);
29.         var map = _byDate.GetOrAdd(
30.             manualOverride.BusinessDate,
31.             _ => new ConcurrentDictionary<string, ManualOverride>(StringComparer.Ordinal));
32.         map[manualOverride.BreakKey] = manualOverride;
33.         return Task.CompletedTask;
34.     }
35. }
