351. 
352.         await using var lockStream = new FileStream(lockPath, FileMode.OpenOrCreate, FileAccess.ReadWrite, FileShare.None);
353.         if (!OperatingSystem.IsMacOS())
354.         {
355.             lockStream.Lock(0, 0);
356.         }
357. 
358.         try
359.         {
360.             var state = await LoadStateAsync(stateDirectory).ConfigureAwait(false);
361.             var result = await action(state).ConfigureAwait(false);
362.             await PersistStateAsync(stateDirectory, state).ConfigureAwait(false);
363.             return result;
364.         }
365.         finally
366.         {
367.             if (!OperatingSystem.IsMacOS())
368.             {
369.                 lockStream.Unlock(0, 0);
370.             }
371.         }
372.     }
